#!/bin/bash
# atlas-probe @@VERSION@@ -- read-only inventory probe for Debian/Ubuntu (ADR-002).
# Generated by `atlas targets render`; do not edit by hand (the collector pins its SHA-256).
#
# Install root-owned 0755 at @@PROBE@@. Runs as root via sudo with exactly one argument
# from a fixed list. It only reads: no writes, no network, no package manager actions.
# Output is framed with a random per-run boundary so collected data cannot forge headers:
#   ATLAS-PROBE 1 <section> <boundary>
#   --<boundary> part <name>
#   ...raw output...
#   --<boundary> rc <exit-code>
set -uo pipefail
umask 077
export PATH=/usr/sbin:/usr/bin:/sbin:/bin
export LC_ALL=C
readonly VERSION="@@VERSION@@"
readonly TMO=20

if [ "$#" -ne 1 ]; then
    echo "atlas-probe: exactly one argument" >&2
    exit 64
fi
section="$1"

B="$(od -An -N12 -tx1 /dev/urandom | tr -d ' \n')"
[ "${#B}" -eq 24 ] || { echo "atlas-probe: no entropy" >&2; exit 70; }

part() {
    # part <name> <command...>: run a fixed, read-only command with a timeout.
    local name="$1"
    shift
    printf -- '--%s part %s\n' "$B" "$name"
    timeout "$TMO" "$@" 2>/dev/null
    local rc=$?
    printf -- '\n--%s rc %d\n' "$B" "$rc"
}

safe_name() {
    # Only plain file names become part names; anything odd is skipped, not echoed.
    case "$1" in
        *[!A-Za-z0-9._/-]*) return 1 ;;
        *) return 0 ;;
    esac
}

files() {
    # files <prefix> <path...>: emit each readable regular file as its own part.
    local prefix="$1" f
    shift
    for f in "$@"; do
        [ -f "$f" ] && [ ! -L "$f" ] || continue
        safe_name "$f" || continue
        part "$prefix:$f" cat -- "$f"
    done
}

printf 'ATLAS-PROBE 1 %s %s\n' "$section" "$B"

case "$section" in
    version)
        part version printf '%s\n' "$VERSION"
        part sha256 sha256sum -- "$0"
        ;;
    os)
        part os-release cat /etc/os-release
        part kernel uname -r
        part arch uname -m
        part hostname hostname
        part machine-id cat /etc/machine-id
        part uptime cat /proc/uptime
        part virt systemd-detect-virt
        part timezone timedatectl show --property=Timezone --value
        ;;
    net)
        part addr ip -j addr show
        part link ip -j -d link show
        part route4 ip -j -4 route show table main
        part route6 ip -j -6 route show table main
        part neigh ip -j neigh show
        part resolv cat /etc/resolv.conf
        ;;
    ports)
        part listen ss -H -t -u -l -n -p
        ;;
    storage)
        part lsblk lsblk -J -b -o NAME,TYPE,SIZE,FSTYPE,MOUNTPOINT,MODEL
        part findmnt findmnt -J -b -o TARGET,SOURCE,FSTYPE,SIZE,USED,AVAIL
        ;;
    services)
        part units systemctl list-units --type=service --all --no-legend --no-pager --output=json
        part unit-files systemctl list-unit-files --type=service --no-legend --no-pager --output=json
        part timers systemctl list-timers --all --no-legend --no-pager --output=json
        ;;
    cron)
        files cron /etc/crontab /etc/cron.d/* /var/spool/cron/crontabs/*
        ;;
    users)
        part passwd getent passwd
        part group getent group
        ;;
    packages)
        # shellcheck disable=SC2016  # ${...} is dpkg-query format syntax, not shell.
        part dpkg dpkg-query -W -f '${Package}\t${Version}\t${db:Status-Abbrev}\n'
        ;;
    docker | pi)
        echo "atlas-probe: section $section not implemented in $VERSION" >&2
        exit 3
        ;;
    *)
        echo "atlas-probe: unknown section" >&2
        exit 64
        ;;
esac
printf -- '--%s end\n' "$B"
